package com.pets.desktoppets.data

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.LruCache
import org.json.JSONObject
import java.io.Closeable
import java.io.FileInputStream
import java.nio.ByteBuffer

/** One entry of assets/pets/manifest.json (generated by tools/build_assets.py). */
data class CharacterInfo(
    val id: String,
    val name: String,
    val width: Int,
    val height: Int,
    val fps: Float,
    val frameCount: Int,
    val animPath: String,
    val thumbPath: String,
    /** [offset, length] of every WebP frame inside the animation pack. */
    val offsets: LongArray,
) {
    val aspect: Float get() = width.toFloat() / height
    val frameDurationMs: Long get() = (1000f / fps).toLong().coerceAtLeast(1)
}

/** Manifest-driven asset repository. Only metadata is held in memory, never decoded frames. */
class CharacterRepository(private val context: Context) {
    val characters: List<CharacterInfo> by lazy { load() }

    fun byId(id: String?): CharacterInfo? = characters.firstOrNull { it.id == id }
    fun resolve(id: String?): CharacterInfo? = byId(id) ?: characters.firstOrNull()

    private val thumbs = object : LruCache<String, Bitmap>(24) {}

    fun thumb(info: CharacterInfo): Bitmap? {
        thumbs.get(info.id)?.let { return it }
        return try {
            context.assets.open(info.thumbPath).use { BitmapFactory.decodeStream(it) }?.also { thumbs.put(info.id, it) }
        } catch (e: Exception) {
            null // missing / damaged thumbnail: UI shows a placeholder
        }
    }

    private fun load(): List<CharacterInfo> = try {
        val root = JSONObject(context.assets.open("pets/manifest.json").bufferedReader().use { it.readText() })
        val arr = root.getJSONArray("characters")
        buildList {
            for (i in 0 until arr.length()) {
                runCatching {
                    val o = arr.getJSONObject(i)
                    val off = o.getJSONArray("frameOffsets")
                    val flat = LongArray(off.length() * 2)
                    for (k in 0 until off.length()) {
                        flat[k * 2] = off.getJSONArray(k).getLong(0)
                        flat[k * 2 + 1] = off.getJSONArray(k).getLong(1)
                    }
                    val info = CharacterInfo(
                        id = o.getString("id"), name = o.getString("name"),
                        width = o.getInt("width"), height = o.getInt("height"),
                        fps = o.getDouble("fps").toFloat(), frameCount = off.length(),
                        animPath = o.getString("anim"), thumbPath = o.getString("thumb"), offsets = flat,
                    )
                    // Skip entries whose animation file is missing instead of crashing later.
                    context.assets.openFd(info.animPath).close()
                    add(info)
                }
            }
        }
    } catch (e: Exception) {
        emptyList()
    }
}

/**
 * Random access to the WebP frames of one character. The pack stays on disk (uncompressed APK entry);
 * only the requested frame's bytes are read, so memory use is a single encoded frame plus its bitmap.
 */
class FramePack(context: Context, val info: CharacterInfo) : Closeable {
    private val afd = context.assets.openFd(info.animPath)
    private val channel = FileInputStream(afd.fileDescriptor).channel
    private var buf = ByteArray(64 * 1024)

    /** Decodes frame [index]; [reuse] (same size) avoids allocating a new bitmap. Returns null if damaged. */
    @Synchronized
    fun decode(index: Int, reuse: Bitmap? = null): Bitmap? {
        val off = info.offsets[index * 2]
        val len = info.offsets[index * 2 + 1].toInt()
        if (buf.size < len) buf = ByteArray(len)
        val bb = ByteBuffer.wrap(buf, 0, len)
        var pos = afd.startOffset + off
        while (bb.hasRemaining()) {
            val n = channel.read(bb, pos)
            if (n < 0) return null
            pos += n
        }
        val opts = BitmapFactory.Options().apply {
            inMutable = true
            inPreferredConfig = Bitmap.Config.ARGB_8888
            if (reuse != null && reuse.isMutable && !reuse.isRecycled) inBitmap = reuse
        }
        return try {
            BitmapFactory.decodeByteArray(buf, 0, len, opts)
        } catch (e: IllegalArgumentException) {
            opts.inBitmap = null
            BitmapFactory.decodeByteArray(buf, 0, len, opts)
        } catch (e: Exception) {
            null
        }
    }

    override fun close() {
        runCatching { channel.close() }
        runCatching { afd.close() }
    }
}
